import{_ as e,o,c as a,a3 as n}from"./chunks/framework.BveOjhN0.js";const h=JSON.parse('{"title":"Quotations — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Quotations — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/quotations"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Quotations — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/quotations"}]]},"headers":[],"relativePath":"user-guide/quotations.md","filePath":"user-guide/quotations.md","lastUpdated":1785703811000}'),s={name:"user-guide/quotations.md"};function r(i,t,l,c,d,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="quotations-—-user-guide" tabindex="-1">Quotations — User Guide <a class="header-anchor" href="#quotations-—-user-guide" aria-label="Permalink to &quot;Quotations — User Guide&quot;">​</a></h1><h2 id="who-can-use-quotations" tabindex="-1">Who can use Quotations <a class="header-anchor" href="#who-can-use-quotations" aria-label="Permalink to &quot;Who can use Quotations&quot;">​</a></h2><p>Your workspace must have the <strong>Opportunities</strong> module installed, then the <strong>Quotations</strong> module (free from Marketplace — not auto-installed). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>send</code>, <code>accept</code> as needed).</p><p>Without <strong>assign</strong>, you only see quotations assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Quotations</strong> from the sidebar (Sales). Search by title, filter by status, opportunity, or assignee, or toggle <strong>My Quotations</strong>. The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted quotation from the row menu</li><li><strong>Delete permanently</strong> requires <code>quotations.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New quotation</strong></li><li>Choose the related <strong>Opportunity</strong> (required)</li><li>Enter a title, optional contact/company link, currency, valid-until date, and notes</li><li>Add line items (description, quantity, unit price, tax rate) — totals are calculated automatically</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the detail drawer while the quotation is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Send</strong>, content is locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A quotation starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Send</strong> (<code>draft → sent</code>) — marks the quote as sent in the CRM (does not email the customer or attach a PDF yet)</li><li><strong>Accept</strong> (<code>sent → accepted</code>) or <strong>Reject</strong> / <strong>Expire</strong> via the status action</li></ul><p>Invalid transitions (e.g. accepting directly from Draft) are rejected with a validation error.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail drawer or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the quotation</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, note, and delete/restore events</li></ul>',18)])])}const m=e(s,[["render",r]]);export{h as __pageData,m as default};
